import{_ as i,o,c as a,a2 as t}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"ADR 0007 — Navigation policy enforced by a thin native WebView delegate","description":"","frontmatter":{"status":"Accepted","date":"2026-07-31T00:00:00.000Z","deciders":"kasunben","sourceUrl":"https://github.com/sovereignfs/sovereign-mobile/blob/main/docs/adrs/0007-navigation-policy-enforcement.md"},"headers":[],"relativePath":"apps/mobile/adrs/0007-navigation-policy-enforcement.md","filePath":"apps/mobile/adrs/0007-navigation-policy-enforcement.md"}'),n={name:"apps/mobile/adrs/0007-navigation-policy-enforcement.md"};function r(s,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0007-—-navigation-policy-enforced-by-a-thin-native-webview-delegate" tabindex="-1">ADR 0007 — Navigation policy enforced by a thin native WebView delegate <a class="header-anchor" href="#adr-0007-—-navigation-policy-enforced-by-a-thin-native-webview-delegate" aria-label="Permalink to &quot;ADR 0007 — Navigation policy enforced by a thin native WebView delegate&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted. Implements sovereign RFC 0058&#39;s explicit navigation-policy requirement; the mechanism itself is decided in this repo since Capacitor has no built-in plugin for it.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>RFC 0058 requires: &quot;The shell loads only user-configured Sovereign instances in the primary WebView. External links should open in the platform browser or an approved in-app browser surface instead of silently navigating the shell away from the configured instance.&quot; The active instance&#39;s origin is chosen by the user at runtime (per <a href="./0002-universal-one-binary-distribution.html">ADR 0002</a>), so this cannot be a static, build-time allow-list — Capacitor&#39;s <code>server.allowNavigation</code> config doesn&#39;t fit, since it&#39;s fixed at build time and this shell has no fixed instance to list.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>A thin native delegate on each platform intercepts WebView navigation and decides same-origin (allow, stays in the WebView) vs. cross-origin (cancel, open via the system browser instead):</p><ul><li><strong>iOS:</strong> <code>MainViewController.swift</code> (a <code>CAPBridgeViewController</code> subclass, wired in via <code>Main.storyboard</code>&#39;s <code>customClass</code>) takes over as <code>webView.navigationDelegate</code> itself and implements <code>webView(_:decidePolicyFor:decisionHandler:)</code>, comparing the navigation&#39;s target origin against the shell&#39;s currently active instance origin. It keeps a typed reference to Capacitor&#39;s own original <code>WebViewDelegationHandler</code> and forwards every selector it doesn&#39;t implement back to it (standard Foundation proxy-forwarding via <code>responds(to:)</code>/<code>forwardingTarget(for:)</code>) so Capacitor&#39;s own navigation lifecycle handling keeps working for everything this class doesn&#39;t care about. Cross-origin loads are opened via <code>UIApplication.shared.open(_:)</code>.</li><li><strong>Android:</strong> <code>NavigationPolicyWebViewClient.java</code> (a <code>BridgeWebViewClient</code> subclass, installed from <code>MainActivity.java</code>&#39;s overridden <code>load()</code>) does the same origin comparison in <code>shouldOverrideUrlLoading</code>. Cross-origin loads are opened via an <code>ACTION_VIEW</code> <code>Intent</code>.</li></ul><p>The active origin is read from <code>@capacitor/preferences</code>&#39; <code>sovereign.activeUrl</code> key (the same storage <code>store.ts</code> already writes), so native code has no separate source of truth to keep in sync — it reads exactly what the TS shell already persists.</p><h3 id="a-same-origin-load-must-be-decided-directly-never-forwarded" tabindex="-1">A same-origin load must be decided directly, never forwarded <a class="header-anchor" href="#a-same-origin-load-must-be-decided-directly-never-forwarded" aria-label="Permalink to &quot;A same-origin load must be decided directly, never forwarded&quot;">​</a></h3><p>The load-bearing detail, found only by testing against a real instance (see Verified below): for the same-origin case, <strong>do not</strong> forward the decision to Capacitor&#39;s own original handler (iOS: <code>WebViewDelegationHandler</code>; Android: <code>BridgeWebViewClient.shouldOverrideUrlLoading</code> via <code>super</code>, which calls <code>Bridge#launchIntent()</code>). Both of Capacitor&#39;s own defaults compare the navigation&#39;s host against the app&#39;s <em>configured</em> host (<code>localhost</code> / the bundled local scheme) and the static <code>server.allowNavigation</code> list — neither of which has any notion of this shell&#39;s runtime-chosen active instance. The practical effect: forwarding the same-origin case sent the very instance this shell exists to load out to the system browser instead of the app&#39;s own WebView, on both platforms, via the identical mechanism. This shell must call <code>.allow</code> / return <code>false</code> directly for the same-origin case on both platforms — see Verified below for exactly how this was caught.</p><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h2><ul><li><strong>Static <code>server.allowNavigation</code> config.</strong> Doesn&#39;t support a runtime- chosen origin; would require a rebuild per instance, contradicting <a href="./0002-universal-one-binary-distribution.html">ADR 0002</a>.</li><li><strong>No enforcement; rely on the loaded instance&#39;s own link <code>target</code>/<code>rel</code> behavior.</strong> Not this shell&#39;s call to make — a plugin author inside the loaded instance could link anywhere, and RFC 0058&#39;s requirement is explicit that the shell, not the instance, owns this policy.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Two small, platform-native files carry real logic for the first time in this repo — acceptable per <a href="./../../AGENTS.html">AGENTS.md</a>&#39;s &quot;native code only for glue a Capacitor plugin doesn&#39;t already cover&quot; rule, since no plugin covers this.</li><li>Both native delegates must be kept in sync with any future change to how or where the active origin is stored — a change to <code>store.ts</code>&#39;s <code>KEY_ACTIVE_URL</code> key name breaks native enforcement silently unless both platform files are updated in the same change.</li><li><strong>Verified on iOS Simulator against a real instance (2026-08-01), <code>sovereign.openfs.io</code>.</strong> The first implementation had exactly the forwarding bug described above: connecting to a real instance from onboarding sent it to Safari instead of loading it in-app. Root-caused by reading Capacitor&#39;s actual resolved <code>Capacitor.swiftinterface</code> (not guessed) — <code>CAPBridgeViewController</code> doesn&#39;t conform to <code>WKNavigationDelegate</code> itself, Capacitor installs a separate <code>WebViewDelegationHandler</code>, and <em>that</em> object&#39;s default policy is what redirected the load externally once this shell&#39;s delegate forwarded to it. Fixed by deciding <code>.allow</code> directly for the same-origin case (see above) rather than forwarding. Re-verified after the fix: connect, app restart (loads saved instance directly), remove, re-add, and switch (tapping an existing instance row) all now correctly stay in this shell&#39;s own WebView.</li><li><strong>Verified on Android Emulator against the same real instance (2026-08-02).</strong> JDK 21 and the Android SDK/emulator (arm64-v8a, API 34) were installed directly (not via Homebrew — this machine&#39;s Homebrew Cellar had broken directory ownership requiring a <code>sudo chown</code> only the machine owner can run) into this repo&#39;s gitignored <code>.toolchain/</code>. <code>./gradlew assembleDebug</code> succeeded, and the identical forwarding fix (<code>NavigationPolicyWebViewClient.java</code> returning <code>false</code> directly instead of forwarding to <code>super</code>/<code>Bridge#launchIntent()</code>) was confirmed correct at runtime, not just by code inspection: connect, restart (loads saved instance directly), and the same-origin case staying in-app (<code>topResumedActivity</code> / <code>dumpsys</code> confirmed <code>fs.sovereign.mobile/.MainActivity</code> stayed foreground, not a browser) were all reproduced on-device, matching iOS.</li><li><strong>Cross-origin click-through verified on a real physical iPhone (2026-08-06).</strong> Built, signed, installed, and launched on a connected iPhone 15 Pro via <code>xcodebuild -allowProvisioningUpdates</code> + <code>xcrun devicectl</code>; a human tester tapped an actual external link (from <code>sovereign.openfs.io</code>&#39;s real sign-in page) and confirmed it opened in Safari, staying out of the primary app view — closing the &quot;still not verified&quot; gap noted above, at least for iOS. The same tester also reconfirmed the same-origin path end-to-end on real hardware: onboarding, connect, sign-in, force-quit/relaunch persistence, and switching back into the listed instance all stayed in-app as expected. <strong>Still not verified:</strong> the equivalent cross-origin click-through on a real Android device (no physical Android device was available this session).</li></ul>',15)])])}const u=i(n,[["render",r]]);export{p as __pageData,u as default};
